10	    [Test]
11	    procedure CheckOutMarksVehicleCheckedOut()
12	    var
13	        Vehicle: Record "CGR Vehicle";
14	        Contract: Record "CGR Rental Contract";
15	        RentalMgt: Codeunit "CGR Rental Mgt";
16	        ContractNo: Code[20];
17	    begin
18	        Lib.CreateVehicle('T-RENT-001', 1000, Enum::"CGR Maintenance Strategy"::Default);
19	        ContractNo := Lib.CreateContract('T-RENT-001');
20	        RentalMgt.CheckOut(ContractNo);
21	        Vehicle.Get('T-RENT-001');
22	        Assert.IsTrue(Vehicle."Checked Out", 'Fleet subscriber must mark the vehicle checked out');
23	        Contract.Get(ContractNo);
24	        Assert.AreEqual(Contract.Status::"Checked Out", Contract.Status, 'Contract status after checkout');
25	        Assert.AreEqual(1000, Contract."Start Km", 'Start km is the vehicle mileage at checkout');
